const pptxgen = require("pptxgenjs");
const path = require("path");

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.author = "Climate Policy Analytics";
pres.title = "Global CO₂ Emissions: Trends, Regional Shifts, and Per Capita Inequalities";

// Color palette — Ocean/Deep Blue for authoritative climate data
const C = {
  darkNavy: "1B2838",
  navy: "1E3A5F",
  teal: "0E7C86",
  lightTeal: "14A3AD",
  accent: "E8443A",
  warmOrange: "F4845F",
  lightBg: "F4F7FA",
  cardBg: "FFFFFF",
  darkText: "1E293B",
  mutedText: "64748B",
  lightText: "CBD5E1",
  white: "FFFFFF",
  gridLine: "E2E8F0",
};

const FONTS = { header: "Georgia", body: "Calibri" };

// ============================================================
// SLIDE 1: Title
// ============================================================
let slide1 = pres.addSlide();
slide1.background = { color: C.darkNavy };

// Subtle decorative shape
slide1.addShape(pres.shapes.RECTANGLE, {
  x: 0, y: 0, w: 10, h: 0.08, fill: { color: C.teal }
});
slide1.addShape(pres.shapes.RECTANGLE, {
  x: 0, y: 5.545, w: 10, h: 0.08, fill: { color: C.teal }
});

slide1.addText("Global CO₂ Emissions", {
  x: 0.8, y: 1.2, w: 8.4, h: 1.2,
  fontSize: 40, fontFace: FONTS.header, color: C.white, bold: true,
  align: "left", valign: "middle", margin: 0
});
slide1.addText("Trends, Regional Shifts, and Per Capita Inequalities", {
  x: 0.8, y: 2.3, w: 8.4, h: 0.7,
  fontSize: 22, fontFace: FONTS.header, color: C.lightTeal, italic: true,
  align: "left", valign: "middle", margin: 0
});
slide1.addText("Scope: 1750–2024  |  Data: Global Carbon Budget 2025, NASA/NOAA", {
  x: 0.8, y: 3.5, w: 8.4, h: 0.5,
  fontSize: 13, fontFace: FONTS.body, color: C.lightText,
  align: "left", valign: "middle", margin: 0
});
slide1.addText("Prepared for policy analysts and climate negotiators", {
  x: 0.8, y: 4.8, w: 8.4, h: 0.4,
  fontSize: 11, fontFace: FONTS.body, color: C.mutedText,
  align: "left", valign: "bottom", margin: 0
});

// ============================================================
// SLIDE 2: Atmospheric CO₂ Milestone
// ============================================================
let slide2 = pres.addSlide();
slide2.background = { color: C.lightBg };

slide2.addText("Atmospheric CO₂ Reaches 429 ppm — 50% Above Pre-Industrial Levels", {
  x: 0.6, y: 0.3, w: 8.8, h: 0.7,
  fontSize: 22, fontFace: FONTS.header, color: C.darkText, bold: true,
  align: "left", valign: "middle", margin: 0
});

// Big stat callout
slide2.addShape(pres.shapes.RECTANGLE, {
  x: 0.6, y: 1.2, w: 4.0, h: 2.8,
  fill: { color: C.cardBg },
  shadow: { type: "outer", color: "000000", blur: 8, offset: 2, angle: 135, opacity: 0.08 }
});
slide2.addText("429", {
  x: 0.6, y: 1.4, w: 4.0, h: 1.5,
  fontSize: 72, fontFace: FONTS.header, color: C.teal, bold: true,
  align: "center", valign: "middle", margin: 0
});
slide2.addText("parts per million (Feb 2026)", {
  x: 0.6, y: 2.8, w: 4.0, h: 0.5,
  fontSize: 14, fontFace: FONTS.body, color: C.mutedText,
  align: "center", valign: "middle", margin: 0
});
slide2.addText("NOAA Mauna Loa Observatory", {
  x: 0.6, y: 3.3, w: 4.0, h: 0.4,
  fontSize: 11, fontFace: FONTS.body, color: C.mutedText, italic: true,
  align: "center", valign: "middle", margin: 0
});

// Context box
slide2.addShape(pres.shapes.RECTANGLE, {
  x: 5.2, y: 1.2, w: 4.2, h: 2.8,
  fill: { color: C.cardBg },
  shadow: { type: "outer", color: "000000", blur: 8, offset: 2, angle: 135, opacity: 0.08 }
});
slide2.addText([
  { text: "Pre-industrial baseline: ~280 ppm", options: { breakLine: true, fontSize: 13, color: C.darkText } },
  { text: "", options: { breakLine: true, fontSize: 8 } },
  { text: "Current level is >50% above baseline", options: { breakLine: true, fontSize: 13, color: C.darkText, bold: true } },
  { text: "", options: { breakLine: true, fontSize: 8 } },
  { text: "Equivalent to 1.5× the natural increase at the end of the last ice age — achieved in ~200 years vs. thousands of years", options: { breakLine: true, fontSize: 12, color: C.mutedText } },
  { text: "", options: { breakLine: true, fontSize: 8 } },
  { text: "Driven primarily by burning coal, oil, and natural gas", options: { fontSize: 12, color: C.mutedText } },
], {
  x: 5.4, y: 1.4, w: 3.8, h: 2.4,
  fontFace: FONTS.body, align: "left", valign: "top", margin: 0
});

// Timeline annotation bar
slide2.addShape(pres.shapes.RECTANGLE, {
  x: 0.6, y: 4.3, w: 8.8, h: 0.04, fill: { color: C.teal }
});
slide2.addText("280 ppm (1750)                              ~315 ppm (1958, Keeling Curve begins)                              429 ppm (2026)", {
  x: 0.6, y: 4.4, w: 8.8, h: 0.4,
  fontSize: 10, fontFace: FONTS.body, color: C.mutedText,
  align: "center", valign: "top", margin: 0
});

// ============================================================
// SLIDE 3: Global Emissions Six-Fold Since 1950
// ============================================================
let slide3 = pres.addSlide();
slide3.background = { color: C.lightBg };

slide3.addText("Global Fossil Fuel CO₂ Emissions Grew Six-Fold: 6 Bt to 35+ Bt", {
  x: 0.6, y: 0.3, w: 8.8, h: 0.7,
  fontSize: 22, fontFace: FONTS.header, color: C.darkText, bold: true,
  align: "left", valign: "middle", margin: 0
});

// Three stat callout cards
const milestones = [
  { year: "1950", val: "6 Bt", note: "Post-war baseline" },
  { year: "1990", val: "20 Bt", note: "Quadrupled in 40 years" },
  { year: "2024", val: "35+ Bt", note: "Still rising, not yet peaked" },
];
milestones.forEach((m, i) => {
  const xPos = 0.6 + i * 3.1;
  slide3.addShape(pres.shapes.RECTANGLE, {
    x: xPos, y: 1.2, w: 2.8, h: 1.6,
    fill: { color: C.cardBg },
    shadow: { type: "outer", color: "000000", blur: 6, offset: 2, angle: 135, opacity: 0.08 }
  });
