const pptxgen = require("pptxgenjs");
const path = require("path");

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.author = "Climate Policy Analytics";
pres.title = "Global CO₂ Emissions: Trends, Regional Shifts, and Per Capita Inequalities";

// Color palette — Ocean/Deep Blue for authoritative climate data
const C = {
  darkNavy: "1B2838",
  navy: "1E3A5F",
  teal: "0E7C86",
  lightTeal: "14A3AD",
  accent: "E8443A",
  warmOrange: "F4845F",
  lightBg: "F4F7FA",
  cardBg: "FFFFFF",
  darkText: "1E293B",
  mutedText: "64748B",
  lightText: "CBD5E1",
  white: "FFFFFF",
  gridLine: "E2E8F0",
};

const FONTS = { header: "Georgia", body: "Calibri" };

// ============================================================
// SLIDE 1: Title
// ============================================================
let slide1 = pres.addSlide();
slide1.background = { color: C.darkNavy };

// Subtle decorative shape
slide1.addShape(pres.shapes.RECTANGLE, {
  x: 0, y: 0, w: 10, h: 0.08, fill: { color: C.teal }
});
slide1.addShape(pres.shapes.RECTANGLE, {
  x: 0, y: 5.545, w: 10, h: 0.08, fill: { color: C.teal }
});

slide1.addText("Global CO₂ Emissions", {
  x: 0.8, y: 1.2, w: 8.4, h: 1.2,
  fontSize: 40, fontFace: FONTS.header, color: C.white, bold: true,
  align: "left", valign: "middle", margin: 0
});
slide1.addText("Trends, Regional Shifts, and Per Capita Inequalities", {
  x: 0.8, y: 2.3, w: 8.4, h: 0.7,
  fontSize: 22, fontFace: FONTS.header, color: C.lightTeal, italic: true,
  align: "left", valign: "middle", margin: 0
});
slide1.addText("Scope: 1750–2024  |  Data: Global Carbon Budget 2025, NASA/NOAA", {
  x: 0.8, y: 3.5, w: 8.4, h: 0.5,
  fontSize: 13, fontFace: FONTS.body, color: C.lightText,
